app.post('/api/settings/test',requireRole('administrator'),async(req,res)=>{const {kind,url}=z.object({kind:z.enum(['incoming','environmental','specifications','reportFolder']),url:z.string()}).parse(req.body);const managed=await getConfiguration();let details:any;if(kind==='reportFolder'){const folder=await driveFolder(url);if(folder.mimeType!=='application/vnd.google-apps.folder')throw new Fault(400,'Choose a Google Drive folder');if(!folder.capabilities?.canAddChildren)throw new Fault(403,'The IPI service account needs Editor access to this folder');details={title:folder.name,folderId:folder.id,writable:true};}else if(kind==='specifications'){const rows=await readApplicability(url);details={rows:rows.length};}else{const book=await readWorkbook(url);const catalog=await sourceTypes();const current=currentMonth(new Date(),managed.value.general.timezone);const currentTabs=book.sheets.filter(sheet=>{const date=monthOf(sheet.name);return date?.year===current.year&&date.month===current.month;});if(currentTabs.length!==1)throw new Fault(409,'Exactly one current-month tab is required. No other month will be used.');const types=catalog.filter(t=>t.register===kind);for(const s of book.sheets)for(const t of types)sourceLayout(s,t.id,t,new Date(),managed.value.general.timezone);details={title:book.title,tabs:book.sheets.map(s=>s.name),validatedSections:book.sheets.length*types.length};}const tests=await setting<any>('connectionTests',{});tests[kind]={url,time:new Date().toISOString(),fingerprint:kind==='reportFolder'?undefined:connectionFingerprint(managed.value,kind),configurationRevision:managed.revision,details};await setSetting('connectionTests',tests);await audit(req.user.email,'connection_tested',kind,{...details,configurationRevision:managed.revision});res.json(details);});
