function documentField(evidence:any,label:string){
 const key=label.normalize('NFKC').replace(/[^a-z0-9]/gi,'').toLowerCase();
 for(const table of evidence.tables||[])for(const row of table.rows||[])for(let i=0;i<row.length;i++){
  if(String(row[i]||'').normalize('NFKC').replace(/[^a-z0-9]/gi,'').toLowerCase()!==key)continue;
  let next=i+1;while(next<row.length&&/^\s*:?\s*$/.test(String(row[next]||'')))next++;
  if(next<row.length)return String(row[next]||'').trim();
 }
 return '';
}
function isoActivityDate(value:string){
 const iso=value.match(/\b(\d{4})-(\d{1,2})-(\d{1,2})\b/);if(iso)return `${iso[1]}-${iso[2].padStart(2,'0')}-${iso[3].padStart(2,'0')}`;
 // Logbook activity dates use month/day/year, matching report resolution.
 const mdY=value.match(/\b(\d{1,2})\/(\d{1,2})\/(\d{4})\b/);if(mdY&&Number(mdY[1])<=12&&Number(mdY[2])<=31)return `${mdY[3]}-${mdY[1].padStart(2,'0')}-${mdY[2].padStart(2,'0')}`;
 return '';
}
app.get('/api/references/:id/environmental-pattern',requireRole('administrator'),async(req,res)=>{
 const source=(await db.query('SELECT data FROM files WHERE id=$1',[req.params.id])).rows[0]?.data;
 if(!source||source.kind!=='reference')throw new Fault(404,'Inspected reference document not found');
 const evidence=await worker(['inventory','--input',privatePath(source.path),...(/\bGIP\b/i.test(source.name)?['--family','environmental-gip-4c']:[])]);
 if(!evidence.environmentalPattern)throw new Fault(409,'This document has no supported environmental results table.');
 const mlText=[documentField(source.evidence,'Logbook'),...(source.evidence.paragraphs||[]).map((p:any)=>p.text)].join(' '),ml=mlText.match(/\bML\s*-\s*EM\s*-\s*\d{2,4}\s*-\s*\d+\b/i)?.[0]?.replace(/\s+/g,'')||'';
 const matched=ml?(await db.query("SELECT data FROM samples WHERE data->>'ml'=$1 ORDER BY updated_at DESC LIMIT 1",[ml])).rows[0]?.data:null;
 const reportArea=documentField(source.evidence,'Area');
 const areaMatch=reportArea.match(/\b(Filling|Compounding|Weighing)\s*(?:Area)?\b/i);
 const areas=(evidence.environmentalPattern.blocks||[]).flatMap((b:any)=>b.instances||[]).map((r:any)=>String(r.location||'').trim()).filter(Boolean);
 const locations=[...new Set(areas)];
 const equipmentCount=String(matched?.fields?.equipmentCount||'').trim();
 const inferredEquipment=[equipmentCount?`${equipmentCount} monitored items`: '',locations.length?locations.join(', '):''].filter(Boolean).join(' · ').slice(0,195);
 const received=String(matched?.received||documentField(source.evidence,'Date&Time Received'));
 const hints={product:String(matched?.name||documentField(source.evidence,'Name of Sample')).trim(),category:matched?.category||'EM',facility:String(matched?.fields?.facility||(/\b(PF\d+)\b/i.exec(reportArea)?.[1]||'')),area:String(matched?.fields?.area||areaMatch?.[1]||''),context:String(matched?.context||''),equipmentSet:inferredEquipment,effectiveFrom:isoActivityDate(received),effectiveThrough:'',sourceML:ml,matchedActivity:Boolean(matched),evidenceDate:received,locations:[...new Set(areas)]};
 res.json({sourceId:req.params.id,name:source.name,sha256:evidence.sha256,pattern:evidence.environmentalPattern,hints});
});

